#!/usr/bin/env python3
"""Lab version of our plugin CI's skill checks: frontmatter, a when-to-use line, loud words, dead links."""
import re
import sys
from pathlib import Path

LOUD = re.compile(r"\b(MUST|NEVER|ALWAYS|CRITICAL|IMPORTANT)\b")
LINK = re.compile(r"\b(references/[\w./-]+\.md)\b")


def check(path: Path) -> tuple[list[str], list[str]]:
    text = path.read_text()
    front, _, body = text.removeprefix("---\n").partition("\n---\n")
    if not text.startswith("---\n") or not body:
        return [f"{path}: no frontmatter"], []
    fields = dict(line.split(":", 1) for line in front.splitlines() if ":" in line)
    fields = {key.strip(): value.strip().strip('"') for key, value in fields.items()}
    errors, warnings = [], []
    if fields.get("name") != path.parent.name:
        errors.append(f"{path}: name does not match the folder {path.parent.name}")
    about = fields.get("description", "") + " " + fields.get("when_to_use", "")
    if len(about) > 600:
        errors.append(f"{path}: description + when_to_use is {len(about)} characters (our limit is 600)")
    if not re.search(r"\buse (when|before|after|for)\b", about, re.I):
        errors.append(f"{path}: the description does not say when to use the skill")
    for n, line in enumerate(body.splitlines(), 1):
        if LOUD.search(line):
            warnings.append(f"{path}: body line {n}: loud words; give the reason instead")
        for link in LINK.findall(line):
            if not (path.parent / link).exists():
                errors.append(f"{path}: body line {n}: {link} does not exist")
    return errors, warnings


results = [check(Path(arg)) for arg in sys.argv[1:]]
for errors, warnings in results:
    print("\n".join(["ERROR " + e for e in errors] + ["warn  " + w for w in warnings]) or "ok")
sys.exit(1 if any(errors for errors, _ in results) else 0)
EOF
